1	import React, { useState, useCallback, useEffect, useMemo } from "react";
2	import { useSearchParams, useLocation } from "react-router-dom";
3	import { useQuery, useQueryClient } from "@tanstack/react-query";
4	import { useAuth } from "@/hooks/useAuth";
5	import { supabase } from "@/integrations/supabase/client";
6	import AppHeader from "@/components/AppHeader";
7	import AuthDialog from "@/components/AuthDialog";
8	import JobSidebar from "@/components/JobSidebar";
9	import JobDetailView from "@/components/JobDetailView";
10	import JobsOverviewCard from "@/components/JobsOverviewCard";
11	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
12	import { Card, CardContent } from "@/components/ui/card";
13	import { Badge } from "@/components/ui/badge";
14	import { Button } from "@/components/ui/button";
15	import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
16	import { format } from "date-fns";
17	import { toast } from "sonner";
18	
19	export interface PastJob {
20	  id: string;
21	  title: string | null;
22	  job_description: string;
23	  status: string;
24	  created_at: string;
25	  resume_count: number;
26	  jd_analysis_json: any;
27	  dynamic_weights_json: Record<string, number> | null;
28	  inbox_email: string | null;
29	}
30	
31	export interface Result {
32	  id: string;
33	  resume_id: string;
34	  overall_score: number;
35	  missing_skills: string[];
36	  summary: string | null;
37	  interview_questions: any;
38	  filename: string;
39	  file_path: string | null;
40	  candidate_name: string | null;
41	  candidate_email?: string | null;
42	  candidate_phone?: string | null;
43	  candidate_location?: string | null;
44	  // Dynamic scoring fields
45	  hard_fit?: boolean;
46	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
47	  confidence?: number;
48	  strengths_json?: string[];
49	  gaps_json?: string[];
50	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
51	  matched_must_haves?: string[];
52	  missing_must_haves?: string[];
53	  scoring_version?: string;
54	  pending?: boolean;
55	  parsed_json?: any;
56	}
57	
58	export interface ExistingResume {
59	  id: string;
60	  filename: string;
61	  file_path: string | null;
62	  candidate_name: string | null;
63	  created_at: string;
64	}
65	
66	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
67	
68	const Index = () => {
69	  const { user, profile } = useAuth();
70	  const [searchParams, setSearchParams] = useSearchParams();
71	  const location = useLocation();
72	
73	  const queryClient = useQueryClient();
74	
75	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
76	    queryKey: ["pastJobs", user?.id],
77	    queryFn: async () => {
78	      const { data: jobs } = await supabase
79	        .from("jobs")
80	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
81	        .eq("user_id", user!.id)
82	        .order("created_at", { ascending: false })
83	        .limit(50);
84	      if (!jobs) return [];
85	      return jobs.map((j: any) => ({
86	        id: j.id,
87	        title: j.title,
88	        job_description: j.job_description,
89	        status: j.status,
90	        created_at: j.created_at,
91	        resume_count: j.resumes?.[0]?.count ?? 0,
92	        jd_analysis_json: j.jd_analysis_json,
93	        dynamic_weights_json: j.dynamic_weights_json,
94	        inbox_email: j.inbox_email ?? null,
95	      })) as PastJob[];
96	    },
97	    enabled: !!user,
98	    staleTime: 2 * 60 * 1000,
99	  });
100	
101	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
102	  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
103	  const [results, setResults] = useState<Result[]>([]);
104	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
105	  const [authOpen, setAuthOpen] = useState(false);
106	
107	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
108	
109	  // Sync view with route path
110	  useEffect(() => {
111	    if (location.pathname === "/jobs") {
112	      setView("my-jobs");
113	      setSelectedJobId(null);
114	    }
115	  }, [location.pathname]);
116	
117	  // Handle URL params for deep linking
118	  useEffect(() => {
119	    const jobParam = searchParams.get("job");
120	    const newParam = searchParams.get("new");
121	
122	    if (jobParam && user) {
123	      loadJobData(jobParam);
124	      setSearchParams({}, { replace: true });
125	    } else if (newParam && user) {
126	      handleNewJob();
127	      setSearchParams({}, { replace: true });
128	    }
129	    // eslint-disable-next-line react-hooks/exhaustive-deps
130	  }, [searchParams, user]);
131	
132	  const loadJobData = async (jobId: string) => {
133	    setSelectedJobId(jobId);
134	    setView("job-detail");
135	    try {
136	      // Single query for all resume data (was 2 separate queries)
137	      const { data: allResumes } = await supabase
138	        .from("resumes")
139	        .select("id, filename, file_path, candidate_name, created_at, parsed_json")
140	        .eq("job_id", jobId)
141	        .order("created_at", { ascending: false });
142	
143	      const resumeData = allResumes ?? [];
144	      setExistingResumes(resumeData.map((r) => ({
145	        id: r.id, filename: r.filename, file_path: r.file_path,
146	        candidate_name: r.candidate_name, created_at: r.created_at,
147	      })));
148	
149	      if (resumeData.length === 0) {
150	        setResults([]);
151	        return;
152	      }
153	
154	      const resumeIds = resumeData.map((r) => r.id);
155	      const { data: resultData } = await supabase
156	        .from("results")
157	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
158	        .in("resume_id", resumeIds);
159	
160	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
161	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
162	        const resume = resumeMap.get(r.resume_id);
163	        const parsed = resume?.parsed_json as any;
164	        return {
165	          ...r,
166	          overall_score: r.overall_score ?? 0,
167	          missing_skills: r.missing_skills ?? [],
168	          filename: resume?.filename ?? "Unknown",
169	          file_path: resume?.file_path ?? null,
170	          candidate_name: resume?.candidate_name ?? null,
171	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
172	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
173	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
174	          parsed_json: resume?.parsed_json ?? null,
175	        };
176	      });
177	      // Deduplicate by resume_id — keep highest scoring result per resume
178	      const deduped = new Map<string, Result>();
179	      for (const r of allMerged) {
180	        const existing = deduped.get(r.resume_id);
181	        if (!existing || r.overall_score > existing.overall_score) {
182	          deduped.set(r.resume_id, r);
183	        }
184	      }
185	      const merged = Array.from(deduped.values());
186	      merged.sort((a, b) => b.overall_score - a.overall_score);
187	      setResults(merged);
188	    } catch (err) {
189	      toast.error("Failed to load job data");
190	    }
191	  };
192	
193	  const handleNewJob = () => {
194	    setSelectedJobId(null);
195	    setView("new-job");
196	    setResults([]);
197	    setExistingResumes([]);
198	  };
199	
200	  const handleGoToDashboard = () => {
201	    setSelectedJobId(null);
202	    setView("dashboard");
203	    setResults([]);
204	    setExistingResumes([]);
205	  };
206	
207	  const handleGoToMyJobs = () => {
208	    setSelectedJobId(null);
209	    setView("my-jobs");
210	    setResults([]);
211	    setExistingResumes([]);
212	  };
213	
214	  const handleJobCreated = (job: PastJob) => {
215	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) => [job, ...(prev ?? [])]);
216	    setSelectedJobId(job.id);
217	    loadJobData(job.id);
218	  };
219	
220	  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
221	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
222	      (prev ?? []).map((j) => (j.id === jobId ? { ...j, ...updates } : j))
223	    );
224	  };
225	
226	  const handleDeleteJobs = async (jobIds: string[]) => {
227	    await supabase.from("jobs").delete().in("id", jobIds);
228	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
229	      (prev ?? []).filter((j) => !jobIds.includes(j.id))
230	    );
231	  };
232	
233	  const requireAuth = useCallback(() => {
234	    if (!user) { setAuthOpen(true); return true; }
235	    return false;
236	  }, [user]);
237	
238	  return (
239	    <SidebarProvider className="h-svh overflow-hidden">
240	      <JobSidebar
241	        showDashboard={view === "dashboard"}
242	        showMyJobs={view === "my-jobs" || view === "job-detail"}
243	        onNewJob={handleNewJob}
244	        onDashboard={handleGoToDashboard}
245	        onMyJobs={handleGoToMyJobs}
246	        onAuthRequired={() => setAuthOpen(true)}
247	        isAuthenticated={!!user}
248	      />
249	
250	      <SidebarInset className="h-svh overflow-y-auto">
251	        <AppHeader />
252	        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
253	          <SidebarTrigger />
254	          <span className="ml-2 text-sm font-medium text-muted-foreground">Menu</span>
255	        </div>
256	
257	        {/* Dashboard view */}
258	        {view === "dashboard" && user ? (
259	          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
260	            {/* Hero Section — Greeting + Create Button */}
261	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
262	              <div>
263	                <h1 className="text-2xl font-bold text-foreground">
264	                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
265	                </h1>
266	                <p className="text-sm text-muted-foreground mt-1">
267	                  Here's an overview of your hiring activity and insights.
268	                </p>
269	              </div>
270	              <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleNewJob}>
271	                <Plus className="h-4 w-4" /> Create Job
272	              </Button>
273	            </div>
274	
275	            {/* Stats Cards */}
276	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
277	              {[
278	                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
279	                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
280	                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
281	                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
282	              ].map((s) => (
283	                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
284	                  <CardContent className="px-5 py-4 flex items-center gap-4">
285	                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
286	                      <s.icon className="h-5 w-5" />
287	                    </div>
288	                    <div>
289	                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
290	                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
291	                    </div>
292	                  </CardContent>
293	                </Card>
294	              ))}
295	            </div>
296	
297	            {/* Recent Jobs */}
298	            {pastJobs.length > 0 && (
299	              <div className="space-y-3">
300	                <div className="flex items-center justify-between">
301	                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
302	                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
303	                    View All Jobs →
304	                  </button>
305	                </div>
306	                <div className="grid gap-3">
307	                  {pastJobs.slice(0, 5).map((job) => (
308	                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
309	                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
310	                        <div className="flex items-center gap-3 min-w-0">
311	                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
312	                            <Briefcase className="h-4 w-4 text-primary" />
313	                          </div>
314	                          <div className="min-w-0">
315	                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
316	                            <p className="text-xs text-muted-foreground mt-0.5">
317	                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
318	                            </p>
319	                          </div>
320	                        </div>
321	                        <div className="flex items-center gap-3 shrink-0">
322	                          <Badge
323	                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
324	                            className="text-xs"
325	                          >
326	                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
327	                          </Badge>
328	                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
329	                        </div>
330	                      </CardContent>
331	                    </Card>
332	                  ))}
333	                </div>
334	              </div>
335	            )}
336	
337	            {/* Getting started guide — show only for new users */}
338	            {pastJobs.length === 0 && !loadingPastJobs && (
339	              <Card>
340	                <CardContent className="px-5 py-4 space-y-3">
341	                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
342	                  <div className="space-y-2.5">
343	                    {[
344	                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
345	                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
346	                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
347	                    ].map((item) => (
348	                      <div key={item.step} className="flex items-start gap-3 text-sm">
349	                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
350	                        <span className="text-muted-foreground">{item.text}</span>
351	                      </div>
352	                    ))}
353	                  </div>
354	                </CardContent>
355	              </Card>
356	            )}
357	          </div>
358	        ) : view === "my-jobs" && user ? (
359	          /* My Jobs view — full management */
360	          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
361	            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
362	              <div className="space-y-1">
363	                <button
364	                  onClick={handleGoToDashboard}
365	                  className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors group mb-1"
366	                >
367	                  <ChevronLeft className="h-3 w-3 group-hover:-translate-x-0.5 transition-transform duration-150" />
368	                  Dashboard
369	                </button>
370	                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
371	                <p className="text-sm text-muted-foreground">Manage all your job postings.</p>
372	              </div>
373	              <Button size="lg" className="gap-2 shadow-md px-6 shrink-0" onClick={handleNewJob}>
374	                <Plus className="h-4 w-4" /> Create Job
375	              </Button>
376	            </div>
377	            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
378	          </div>
379	        ) : (
380	          <JobDetailView
381	            selectedJobId={selectedJobId}
382	            selectedJob={selectedJob}
383	            results={results}
384	            setResults={setResults}
385	            existingResumes={existingResumes}
386	            setExistingResumes={setExistingResumes}
387	            onJobCreated={handleJobCreated}
388	            onAuthRequired={() => setAuthOpen(true)}
389	            isAuthenticated={!!user}
390	            pastJobs={pastJobs}
391	            onJobUpdated={handleJobUpdated}
392	            onBack={handleGoToMyJobs}
393	          />
394	        )}
395	      </SidebarInset>
396	
397	      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
398	    </SidebarProvider>
399	  );
400	};
401	
402	export default Index;
403	
