84	
85	    --rk-success: 152 50% 55%;
86	    --rk-success-foreground: 0 0% 8%;
87	
88	    --rk-warning: 36 70% 62%;
89	    --rk-warning-foreground: 0 0% 8%;
90	
91	    --rk-border: 220 14% 18%;
92	    --rk-input: 220 14% 18%;
93	    --rk-ring: 217 91% 60%;
94	
95	    --rk-score-overall: 217 91% 65%;
96	    --rk-score-skills: 152 50% 55%;
97	    --rk-score-education: 36 70% 62%;
98	    --rk-score-jd: 346 55% 62%;
99	
100	    --rk-sidebar-background: 220 14% 11%;
101	    --rk-sidebar-foreground: 220 14% 85%;
102	    --rk-sidebar-primary: 217 91% 60%;
